function dfs(nums, depth, prev, res) {
    res.push(prev);
    for (let i = depth; i < nums.length; i++) {
        prev ^= nums[i];
        depth++;
        dfs(nums, depth, prev, res);
        // bracktrack
        prev ^= nums[i];
    }
}
